class Solution { public:
 string largestPalindrome(int n,int k){int half=(n+1)/2;vector<int> pow10(n);pow10[0]=1%k;for(int i=1;i<n;++i)pow10[i]=pow10[i-1]*10%k;
 vector<int> weight(half);for(int i=0;i<half;++i){weight[i]=pow10[i];if(i!=n-1-i)weight[i]=(weight[i]+pow10[n-1-i])%k;}
 vector<vector<char>> can(half+1,vector<char>(k));can[half][0]=1;
 for(int i=half-1;i>=0;--i)for(int d=0;d<=9;++d)for(int r=0;r<k;++r)if(can[i+1][r])can[i][(r+d*weight[i])%k]=1;
 string ans(n,'0');int rem=0;
 for(int i=0;i<half;++i){for(int d=9;d>=1;--d){int nr=(rem+d*weight[i])%k;if(can[i+1][(k-nr)%k]){ans[i]=ans[n-1-i]=char('0'+d);rem=nr;break;}}}
 return ans;}
};
